// Fixing bulk select (only needed for desktop)
.bulk-select-enabled {
  body:not(.user-messages-page) & {
    .topic-list-header {
      position: sticky;
      top: 8em;
      height: 0;
      z-index: 1;
    }

    .topic-author-avatar-data {
      display: none;
    }

    .bulk-select.topic-list-data {
      grid-area: bulk-select;
      margin-left: -0.5em;

      @media screen and (width <= 576px) {
        margin-top: 0;

        label {
          padding-block: 0.345em;
        }
      }

      input {
        transform: scale(1.5);
      }
    }
  }
}

.topic-list-header {
  body:not(.user-messages-page) & {
    tr {
      border: none;
    }

    .topic-list-data {
      padding: 0;

      &:not(.default) {
        display: none;
      }

      &.default {
        .bulk-select,
        span:not(.bulk-select-topics, .d-button-label) {
          display: none;
        }
      }

      .bulk-select-topics {
        position: absolute;
        right: var(--space-2);
        top: var(--space-2);
        background: transparent;
        border-radius: var(--d-border-radius);
        display: flex;
        gap: 0.5rem;
        margin: var(--space-4) 0;
        padding: var(--space-1);

        button {
          white-space: nowrap;
          margin: 0;
        }
      }
    }
  }
}
","@use "lib/viewport";

// Full width layout. Ported from the Discourse Full Width theme component here
// https://meta.discourse.org/t/discourse-full-width-component/292496, which we
// intend to move into core over time.
//
// We are copying this here so we can continue to iterate on Horizon with full
// width without having to include the theme component as a dependency, we
// need to remove this once full width is in core.

$sidebar-width: 17em;

.wrap {
  max-width: unset; // undoing core default
}

.d-header #site-logo {
  // this prevents the logo from shifting header content
  // when the sidebar is opened
  max-height: 100%;
  max-width: 100%;
  object-fit: contain; // contains logo without squishing/stretching

  // allows some flexibility for wide logos
  body:not(.has-sidebar-page) & {
    max-width: unset;

    @include viewport.until(sm) {
      max-width: 25vw;
    }
  }
}

.d-header #site-text-logo {
  font-size: clamp(var(--font-0), 2.5vw, var(--font-up-1));

  .has-sidebar-page & {
    white-space: wrap;
    line-height: var(--line-height-medium);

    @include line-clamp(2);
  }
}

#main-outlet-wrapper {
  body.has-sidebar-page & {
    .sidebar-wrapper {
      width: var(--d-sidebar-width);
    }
  }

  body.has-full-page-chat & {
    gap: 0;
  }

  .sidebar-wrapper {
    width: 100%; // safari has issues without this
  }

  #main-outlet {
    margin: 0 auto;
    max-width: var(--d-max-width);
    width: 100%;

    body.has-full-page-chat & {
      max-width: unset;
    }
  }
}

.has-full-page-chat:not(.discourse-sidebar) .full-page-chat {
  border: none;
}

#main-outlet > .regular {
  max-width: var(--d-max-width);
  margin: 0 auto;

  body.has-sidebar-page & {
    margin: 0 auto;
  }
}

.d-header .title:not(.title--minimized) {
  // allowing overflow here isn't always ideal
  // but works well enough most of the time
  overflow: visible;
}

.d-header {
  > .wrap {
    .contents {
      display: grid;
      grid-template-areas: "logo lspace extra-info rspace panel";
      grid-template-columns:
        minmax(auto, 1fr)
        auto
        minmax(0, calc(var(--d-max-width)))
        auto
        minmax(auto, 1fr);

      .d-header .title {
        min-width: auto;
      }

      .has-sidebar-page & {
        // at wide widths, when 1fr > 0
        // we want the panel to be the same width as the sidebar
        // this way we can get more accurate centering
        grid-template-columns:
          calc(var(--d-sidebar-width) - 11px) // 11px is wrap padding
          1fr
          minmax(0, calc(var(--d-max-width)))
          1fr
          minmax(0, calc(var(--d-sidebar-width) - 11px));
        gap: 1em;

        // at narrower widths, when 1fr = 0
        // we can center without matching the sidebar's width
        // which allows the title to take up the remaining width
        @media screen and (width <= 1400px) {
          grid-template-columns:
            calc(var(--d-sidebar-width) - 11px)
            1fr
            minmax(0, calc(var(--d-max-width)))
            1fr
            auto;
        }

        @media screen and (width <= 1000px) {
          gap: 0.5em;
        }
      }
    }
  }

  .header-sidebar-toggle {
    grid-area: logo;
  }

  .before-header-panel-outlet {
    grid-area: extra-info;
  }

  .home-logo-wrapper-outlet {
    grid-area: logo;
    margin-left: 3.7em; // 2.7em hamburger width + 1em for margin
    margin-right: 0.725em;
    display: flex;
    overflow: visible;

    .title {
      flex: 1 1 auto;
    }
  }

  .panel {
    grid-area: panel;
  }
}

.extra-info-wrapper {
  grid-area: extra-info;
  max-width: var(--d-max-width);
  width: 100%;
  box-sizing: border-box;
  padding: 0;
}

.header-search--enabled .floating-search-input-wrapper {
  grid-area: extra-info;

  @include viewport.until(md) {
    grid-area: rspace;
  }

  @include viewport.until(sm) {
    display: none;
  }
}

body.has-sidebar-page {
  .wrap {
    max-width: unset; // undoing core default
  }

  .extra-info-wrapper {
    padding: 0;
  }

  @media screen and (width >= calc($reply-area-max-width + ($sidebar-width * 2))) {
    #reply-control.show-preview {
      margin-left: auto;
      margin-right: auto;
    }

    .sidebar-container {
      height: auto;
    }
  }

  @media screen and (width <= calc($reply-area-max-width + ($sidebar-width * 2))) and (width >= calc($reply-area-max-width + calc($sidebar-width / 2))) {
    #reply-control.show-preview:not(.fullscreen) {
      margin-left: $sidebar-width;
      width: auto;

      // overruling new core composer changes
      max-width: $reply-area-max-width;
      transform: none;
    }

    .sidebar-container {
      height: auto;
    }
  }

  // overruling new core composer changes
  @media screen and (min-width: $reply-area-max-width) {
    #reply-control.show-preview:not(.fullscreen) {
      max-width: $reply-area-max-width;
      transform: none;
    }
  }
}

body.sidebar-animate {
  #main-outlet-wrapper {
    transition: none;
  }

  .d-header-wrap .wrap {
    transition: none;
  }
}

.d-header-icons {
  display: flex;
}

.rtl {
  .d-header .title {
    margin-right: 3.7em; // 2.7em hamburger width + 1em for margin
    margin-left: 0.725em;
  }
}

// provides some extra space for login buttons
@media screen and (width >= 1400px) {
  .anon {
    .d-header .panel {
      grid-column-start: -4;
    }
  }
}
","@use "breakpoints";

$breakpoints: breakpoints.$breakpoints;

@mixin from($bp) {
  @media (width >= #{breakpoints.get($bp)}) {
    @content;
  }
}

@mixin until($bp) {
  @media (width < #{breakpoints.get($bp)}) {
    @content;
  }
}

@mixin between($from, $until) {
  @media (#{breakpoints.get($from)} <= width < #{breakpoints.get($until)}) {
    @content;
  }
}
","// --------------------------------------------------
// Mixins used throughout the theme
// --------------------------------------------------

// Media queries
// --------------------------------------------------

@use "sass:color";
@use "sass:math";
@use "sass:string";
@use "sass:map";
@use "lib/viewport";

$breakpoints: (
  mobile-small: map.get(viewport.$breakpoints, sm),
  mobile-medium: map.get(viewport.$breakpoints, sm),
  mobile-large: map.get(viewport.$breakpoints, sm),
  mobile-extra-large: map.get(viewport.$breakpoints, sm),
  tablet: map.get(viewport.$breakpoints, md),
  medium: map.get(viewport.$breakpoints, lg),
  large: map.get(viewport.$breakpoints, lg),
  extra-large: map.get(viewport.$breakpoints, xl),
);

/* breakpoint is a legacy mixin. Use `@use "lib/viewport"` instead. */
@mixin breakpoint($bp, $rule: max-width, $type: screen, $sidebar: false) {
  /* stylelint-disable-next-line scss/no-global-function-names */
  $bp-value: map-get($breakpoints, $bp);

  @if $rule == min-width {
    $bp-value: calc(#{$bp-value} + 1px);
  }

  @media #{$type} and (#{$rule}: #{$bp-value}) {
    @content;
  }

  // if you want to consider the sidebar in your breakpoint
  // you can pass in $sidebar: true
  // note that your breakpoint will need to be at the root level
  @if $sidebar {
    // when the sidebar is shown, we want to increase the breakpoints by the width of the sidebar
    /* stylelint-disable-next-line scss/no-global-function-names */
    @media #{$type} and (#{$rule}: calc(#{map-get($breakpoints, $bp)} + #{$d-sidebar-width})) {
      .has-sidebar-page {
        @content;
      }
    }
  }
}

// CSS3 properties
// --------------------------------------------------

// Clearfix

@mixin clearfix() {
  &::before,
  &::after {
    content: "";
    display: table;
  }

  &::after {
    clear: both;
  }
}

@mixin linear-gradient($start-color, $end-color) {
  background-color: $start-color;
  background-image: linear-gradient(to bottom, $start-color, $end-color);
}

@mixin darken-background($background-color, $amt) {
  $overlay: dark-light-choose(
    rgb(var(--primary-rgb), $amt),
    rgb(var(--secondary-rgb), $amt)
  );
  background-image: linear-gradient(to bottom, $overlay 100%, $overlay 100%);
}

// Visibility
// --------------------------------------------------

// Only shows hover on non-touch devices
@mixin hover {
  .discourse-no-touch &,
  .no-ember & {
    &:hover,
    &.btn-hover {
      @content;
    }
  }
}

@mixin ellipsis {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

@mixin line-clamp($lines) {
  display: -webkit-box;
  overflow: hidden;
  text-overflow: ellipsis;
  overflow-wrap: break-word;
  -webkit-line-clamp: $lines;
  -webkit-box-orient: vertical;
}

//
// --------------------------------------------------

$vpad: 0.5em;
$hpad: 0.65em;

// for consistent sizing across inputs, buttons and dropdowns
@mixin form-item-sizing {
  border: 1px solid transparent;
  font-size: var(--font-0);
  line-height: normal;
  box-sizing: border-box;
  padding: $vpad $hpad;
}

// Used to handle -webkit prefix, but now we have autoprefixer
// Keeping for backward-compat with plugins/themes only
@mixin user-select($mode) {
  user-select: $mode;
}

// Unselectable (avoids unwanted selections with iPad, touch laptops, etc)
@mixin unselectable {
  cursor: default;

  @include user-select(none);
}

// Stuff we repeat
@mixin d-animation($name, $duration, $easing: ease) {
  animation: $name $duration $easing forwards;

  @media (prefers-reduced-motion) {
    /* stylelint-disable-next-line no-invalid-position-declaration */
    animation-duration: 0s;
  }
}

@mixin default-focus() {
  border-color: var(--d-input-focused-color);
  outline: 2px solid var(--d-input-focused-color);
  outline-offset: -2px;
}

/// Helper function to easily use an SVG inline in CSS
/// without encoding it to base64, saving bytes.
/// It also helps with browser support, especially for IE11.
///
/// @author Jakob Eriksen
/// @link http://codepen.io/jakob-e/pen/doMoML
/// @param {String} $svg - SVG image to encode
/// @return {String} - Encoded SVG data uri
@function svg-uri($svg) {
  $encoded: "";
  $slice: 2000;
  $index: 0;
  $loops: math.ceil(math.div(string.length($svg), $slice));

  @for $i from 1 through $loops {
    $chunk: string.slice($svg, $index, $index + $slice - 1);
    $chunk: str-replace($chunk, '"', "'");
    $chunk: str-replace($chunk, "<", "%3C");
    $chunk: str-replace($chunk, ">", "%3E");
    $chunk: str-replace($chunk, "&", "%26");
    $chunk: str-replace($chunk, "#", "%23");
    $encoded: #{$encoded}#{$chunk};
    $index: $index + $slice;
  }

  @return url("data:image/svg+xml;charset=utf8,#{$encoded}");
}

/// Replace `$search` with `$replace` in `$string`
/// @author Hugo Giraudel
/// @link http://sassmeister.com/gist/1b4f2da5527830088e4d
/// @param {String} $string - Initial string
/// @param {String} $search - Substring to replace
/// @param {String} $replace ('') - New value
/// @return {String} - Updated string
@function str-replace($string, $search, $replace: "") {
  $index: string.index($string, $search);

  @if $index {
    @return string.slice($string, 1, $index - 1) + $replace +
      str-replace(
        string.slice($string, $index + string.length($search)),
        $search,
        $replace
      );
  }

  @return $string;
}

// SCSS accepts HEX or RGB colors for rgba($color, 0.5)
// CSS custom properties only accept RGB
// Example usage:

// --primary-rgb: #{hexToRGB($primary)};
// ...
// rgba(var(--primary-low-rgb), 0.5)

@function hexToRGB($hex) {
  @return color.red($hex), color.green($hex), color.blue($hex);
}

@function schemeType() {
  @if is-light-color-scheme() {
    @return "light";
  } @else {
    @return "dark";
  }
}

@function absolute-image-url($path) {
  // public_image_path is added by the stylesheet importer
  // it returns a CDN or subfolder path (if applicable).
  // SCSS will compile (and return the relative path) if public_image_path is missing.
  /* stylelint-disable-next-line scss/no-global-function-names */
  @if global-variable-exists(public_image_path) {
    @if string.index("#{$path}", "/plugins") == 1 {
      $plugin_asset_path: str-replace($public_image_path, "/images", "");

      @return url("#{$plugin_asset_path}#{$path}");
    } @else {
      @return url("#{$public_image_path}#{$path}");
    }
  } @else {
    @return url("#{$path}");
  }
}

@mixin mention() {
  // memo to self: do not make this inline-flex because it breaks text alignments and causes a whole avalance of unpleasant consequences
  display: inline-block;
  font-size: 0.93em;
  font-weight: normal;
  color: var(--primary);
  padding: 0.2em 0.34em;
  background: var(--mention-background-color);
  border-radius: 0.6em;
  text-decoration: none;
  text-wrap: nowrap;
  line-height: 1;
  unicode-bidi: plaintext;

  &[data-valid="false"] {
    background: unset;
    padding: 0;
  }

  &.--bot {
    background: var(--success-low);
  }

  &.--wide {
    background: var(--highlight-low-or-medium);
  }
}

@mixin nav-active() {
  color: var(--d-nav-color--active);
  background: var(--d-nav-bg-color--active);

  .d-icon {
    color: var(--d-nav-color--active);
  }

  &::after {
    content: "";
    position: absolute;
    left: 0;
    bottom: 0;
    right: 0;
    height: var(--d-nav-underline-height);
    background: var(--d-nav-color--active);

    // Forced colors drop backgrounds, which is the only thing that marks
    // the active item.
    @media (forced-colors: active) {
      background: Highlight;
      forced-color-adjust: none;
    }
  }
}

@mixin nav-hover() {
  color: var(--d-nav-color--hover);
  background: var(--d-nav-bg-color--hover);

  .d-icon {
    color: var(--d-nav-color--active);
  }
}

// A strip that hides its scrollbar and fades the edge beyond which more
// content lies. The fade reads the data-d-scroll-* attributes stamped by
// the scroll-edges watcher, which DOverflowControls and the dScrollEdges
// modifier both run. The band starts fully transparent across --fade-inset
// so strip content never shows through a chevron parked on the edge, which
// assumes the chevron covers that band: a wrapper that pads the scroller's
// scrolling edge moves the chevron off it and hides content under nothing.
// #000 is deliberate: a mask reads only alpha, so a colour token would be
// wrong here.
@mixin scroll-strip() {
  // The bands are capped so the two ends cannot cross on a narrow strip.
  // Crossed bands leave no opaque middle.
  --scroll-strip-fade-start: min(var(--fade-inset, 0px), 15%);
  --scroll-strip-fade-end: min(
    calc(var(--fade-inset, 0px) + var(--fade-width, 2em)),
    40%
  );
  min-width: 0;
  min-height: 0;
  scrollbar-width: none;
  scroll-padding: calc(var(--fade-inset, 0px) + var(--fade-width, 2em));

  &::-webkit-scrollbar {
    display: none;
  }

  // Forced colors drop the mask, which would otherwise lower text contrast
  // for exactly the users who opted out of decoration.
  @media (forced-colors: none) {
    &[data-d-scroll-axis="horizontal"][data-d-scroll-overflow] {
      mask-image: linear-gradient(
        to right,
        transparent var(--scroll-strip-fade-start),
        #000 var(--scroll-strip-fade-end),
        #000 calc(100% - var(--scroll-strip-fade-end)),
        transparent calc(100% - var(--scroll-strip-fade-start))
      );

      // The edges are logical, the gradients physical, so RTL swaps them.
      &[data-d-scroll-at-start] {
        mask-image: linear-gradient(
          to right,
          #000 calc(100% - var(--scroll-strip-fade-end)),
          transparent calc(100% - var(--scroll-strip-fade-start))
        );

        .rtl & {
          mask-image: linear-gradient(
            to left,
            #000 calc(100% - var(--scroll-strip-fade-end)),
            transparent calc(100% - var(--scroll-strip-fade-start))
          );
        }
      }

      &[data-d-scroll-at-end] {
        mask-image: linear-gradient(
          to right,
          transparent var(--scroll-strip-fade-start),
          #000 var(--scroll-strip-fade-end)
        );

        .rtl & {
          mask-image: linear-gradient(
            to left,
            transparent var(--scroll-strip-fade-start),
            #000 var(--scroll-strip-fade-end)
          );
        }
      }
    }

    &[data-d-scroll-axis="vertical"][data-d-scroll-overflow] {
      mask-image: linear-gradient(
        to bottom,
        transparent var(--scroll-strip-fade-start),
        #000 var(--scroll-strip-fade-end),
        #000 calc(100% - var(--scroll-strip-fade-end)),
        transparent calc(100% - var(--scroll-strip-fade-start))
      );

      &[data-d-scroll-at-start] {
        mask-image: linear-gradient(
          to bottom,
          #000 calc(100% - var(--scroll-strip-fade-end)),
          transparent calc(100% - var(--scroll-strip-fade-start))
        );
      }

      &[data-d-scroll-at-end] {
        mask-image: linear-gradient(
          to bottom,
          transparent var(--scroll-strip-fade-start),
          #000 var(--scroll-strip-fade-end)
        );
      }
    }

    // The .rtl copy only exists to outrank the .rtl at-start/at-end rules
    // above, which score a class higher than the bare selector.
    &[data-d-scroll-overflow][data-d-scroll-at-start][data-d-scroll-at-end],
    .rtl
      &[data-d-scroll-overflow][data-d-scroll-at-start][data-d-scroll-at-end] {
      mask-image: none;
    }
  }
}

// The scroll strip on the horizontal axis. The caller keeps its own items
// on one row; the mixin does not.
@mixin horizontal-scroll-strip() {
  @include scroll-strip;
  overflow-x: auto;
}

@mixin click-counter-badge {
  content: attr(data-clicks);
  font-weight: normal;
  background-color: var(--primary-low);
  color: var(--primary-medium);
  position: relative;
  top: -1px;
  padding: 0.21em 0.42em;
  min-width: 0.5em;
  line-height: var(--line-height-small);
  font-size: var(--font-down-2);
  text-align: center;
  border-radius: 10px;
  white-space: nowrap;
  display: inline-block;
  margin: 0.15em;
}

@mixin topic-list-icons {
  .d-icon-thumbtack {
    color: var(--primary-med-or-secondary-med);
  }

  .d-icon-thumbtack.unpinned {
    color: var(--primary-med-or-secondary-med);
  }

  a.title {
    color: var(--primary);
  }

  .d-icon-bookmark {
    color: var(--primary-med-or-secondary-med);
  }
}

@mixin hide-posters {
  width: 2em;
  text-align: center;

  a:first-child .avatar.latest:not(.single) {
    top: 0;
    left: 0;
  }

  a:not(.latest) {
    display: none;
  }

  a.latest {
    width: 100%;

    img {
      margin: 0 auto;
    }
  }
}

@mixin dot-separator($size: 0.35em) {
  display: inline-block;
  width: $size;
  height: $size;
  margin-inline: var(--space-1);
  border-radius: 6.25em;
  background: var(--primary-low-mid);
  flex-shrink: 0;
}

@mixin menu-item {
  display: inline-flex;
  gap: var(--d-sidebar-section-link-prefix-margin-right);
  padding: var(--space-2) var(--d-sidebar-row-horizontal-padding);
  width: 100%;
  justify-content: flex-start;
  background: rgb(0, 0, 0, 0);
  border-radius: var(--d-border-radius);

  &:not(.notifications-tracking-btn, .--with-description, .pinned-options-btn) {
    height: var(--d-sidebar-row-height);
    padding-block: 0;
  }

  &.-selected {
    background: var(--d-hover);
  }

  &.btn-danger {
    color: var(--danger);

    .d-icon {
      color: inherit;
    }
  }

  .svg-icon {
    width: var(--d-sidebar-section-link-prefix-width);
    margin-right: 0;
  }

  &:hover,
  &:focus-visible {
    .discourse-no-touch & {
      background: var(--d-hover);
      color: var(--primary);

      .d-icon {
        color: inherit;
      }

      &.btn-danger {
        background: var(--danger-low);
        color: var(--danger);

        .d-icon {
          color: var(--danger-hover);
        }
      }
    }
  }
}

@mixin unstyled-list {
  list-style: none;
  padding: 0;
  margin: 0;
}
